static int fwft_menvcfg_set_bit(unsigned long value, unsigned long bit)
{
	if (value == 1) {
		csr_set(CSR_MENVCFG, _ULL(1) << bit);  // no SFENCE.VMA
	} else if (value == 0) {
		csr_clear(CSR_MENVCFG, _ULL(1) << bit);  // no SFENCE.VMA
	}
